const DBNAME='foster_navi_empowerment_protocol_v1',DBSTORE='workspace',LSKEY='fn_ep_backup_v1';let db=null;
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(Error('IndexedDB unavailable'));const request=indexedDB.open(DBNAME,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(DBSTORE))request.result.createObjectStore(DBSTORE)};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error('Storage failed'));request.onblocked=()=>reject(Error('Storage is blocked by another tab'))})}
function idbValue(mode,value){return new Promise((resolve,reject)=>{const tx=db.transaction(DBSTORE,mode),store=tx.objectStore(DBSTORE),req=mode==='readonly'?store.get('snapshot'):store.put(value,'snapshot');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Database request failed'));tx.onerror=()=>reject(tx.error||Error('Database transaction failed'))})}
function text(s,max=1600){return String(s??'').slice(0,max)}
function limitedNumber(v){return v==null||v===''?null:(Number.isFinite(Number(v))&&Math.abs(Number(v))<=1e12?Number(v):null)}
function validateURL(u){if(!u)return '';try{const x=new URL(u);if(x.protocol!=='https:')throw Error('Only HTTPS source links accepted');return x.href.slice(0,1100)}catch{throw Error('Invalid source URL: use https://')}}
function hydrateProject(raw){if(!raw||typeof raw!=='object'||!EBY[raw.engine]||!String(raw.id||'').match(/^[a-zA-Z0-9_-]{5,100}$/))throw Error('Invalid project record');const engine=EBY[raw.engine];const metricIds=engine.metric.map(m=>m[0]);const metric=metricIds.includes(raw.metric)?raw.metric:metricIds[0];if(!Array.isArray(raw.tasks)||raw.tasks.length>35||!Array.isArray(raw.observations)||raw.observations.length>500)throw Error('Record exceeds safe limits');return {id:String(raw.id),engine:engine.id,title:text(raw.title,120),problem:text(raw.problem),context:text(raw.context,1300),budget:limitedNumber(raw.budget)||0,scale:text(raw.scale,80),metric,window:Math.max(1,Math.min(3650,Number(raw.window)||90)),baseline:limitedNumber(raw.baseline),target:limitedNumber(raw.target),created:text(raw.created,35),tasks:raw.tasks.map(t=>({label:text(t.label,180),done:!!t.done})),observations:raw.observations.map(o=>({id:text(o.id,100),date:text(o.date,35),value:limitedNumber(o.value),unit:text(o.unit,80),method:text(o.method,420),note:text(o.note,1000)})),review:text(raw.review,30)}}
function hydrateEvidence(raw){if(!raw||typeof raw!=='object'||!EBY[raw.domain]||!String(raw.id||'').match(/^[a-zA-Z0-9_-]{5,100}$/))throw Error('Invalid evidence record');return {id:String(raw.id),domain:raw.domain,type:text(raw.type,80),claim:text(raw.claim,1200),url:validateURL(raw.url||''),quality:text(raw.quality,100),limits:text(raw.limits,1200),date:text(raw.date,35)}}
function validateBackup(obj){if(!obj||typeof obj!=='object'||![1,2].includes(obj.schema)||!Array.isArray(obj.projects)||!Array.isArray(obj.evidence)||obj.projects.length>200||obj.evidence.length>500||obj.schema===2&&!Array.isArray(obj.genomes)||obj.genomes?.length>GENOME_LIMIT)throw Error('Unsupported schema or record limits (v1 and v2 accepted).');const projects=obj.projects.map(hydrateProject),evidence=obj.evidence.map(hydrateEvidence),genomes=(obj.schema===2?obj.genomes:[]).map(safeGenome);for(const items of [projects,evidence,genomes])if(new Set(items.map(p=>p.id)).size!==items.length)throw Error('Duplicate IDs in imported records');return {schema:2,projects,evidence,research:[],genomes}}
async function loadState(){try{db=await openDB();storeMode='IndexedDB · browser-local';const stored=await idbValue('readonly');if(stored)state=validateBackup(stored)}catch(err){db=null;try{storeMode='LocalStorage fallback · browser-local';const old=localStorage.getItem(LSKEY);if(old)state=validateBackup(JSON.parse(old));else localStorage.setItem(LSKEY,JSON.stringify(state))}catch(e){storeMode='Memory only · EXPORT before closing';console.warn('Persistent storage unavailable:',e.message)}}$('storageStatus').textContent='Storage: '+storeMode+'. No account or sync; back up regularly.';renderAll()}
function persist(){const snapshot=JSON.parse(JSON.stringify(state));saveSequence=saveSequence.catch(()=>{}).then(async()=>{try{if(db)await idbValue('readwrite',snapshot);else if(storeMode.startsWith('LocalStorage'))localStorage.setItem(LSKEY,JSON.stringify(snapshot));else toast('Memory-only mode: export your work before closing.')}catch(e){storeMode='Memory only · EXPORT before closing';$('storageStatus').textContent='Persistent save failed: '+e.message+'. Export now!';toast('Persistent save failed. Export a backup now.')}});return saveSequence}
function projectAsExport(p,privateData,i){const copy=JSON.parse(JSON.stringify(p));if(!privateData){copy.id=makeId();copy.title='Redacted project '+(i+1);copy.problem='';copy.context='';copy.observations=copy.observations.map(o=>({...o,id:makeId(),method:'',note:''}));copy.tasks=copy.tasks.map(t=>({...t,label:'Task label redacted'}))}return copy}
function exportState(privateData){return {app:'Foster + Navi Empowerment Protocol',schema:2,exported:now(),privacy:privateData?'private-unencrypted-backup':'redacted-share-copy',snapshot:SNAPSHOT,projects:state.projects.map((p,i)=>projectAsExport(p,privateData,i)),evidence:privateData?state.evidence:state.evidence.map(n=>({...n,id:makeId(),claim:'',limits:'',url:''})),genomes:privateData?state.genomes.map(g=>safeGenome(g)):[],research:[]}}
async function doImport(){const file=$('importFile').files[0];if(!file)return toast('Choose a JSON file first.');if(file.size>16*1024*1024)return toast('File is over the 16 MB limit.');if(!$('importConfirm').checked)return toast('Confirm the import impact first.');try{const next=validateBackup(JSON.parse(await file.text()));const replacing=$('importMode').value==='replace';if(replacing&&!confirm('Replace all current projects, evidence, and innovation genomes? Export a backup first. This cannot be undone.'))return;const merged=replacing?next:{schema:2,projects:uniqueById([...state.projects,...next.projects]),evidence:uniqueById([...state.evidence,...next.evidence]),genomes:mergeGenomeBackup(state.genomes,next.genomes),research:[]};if(merged.projects.length>200||merged.evidence.length>500||merged.genomes.length>GENOME_LIMIT)throw Error('Merged workspace exceeds limits');state=merged;activeProject=null;selectedGenomeId=null;await persist();renderAll();toast('Import validated and applied'+(storeMode.startsWith('Memory')?' in memory only; export now.':'.'))}catch(e){toast('Import rejected: '+e.message)}}
/* SECTION 4: PRESENTATION + ROUTING -----------------------------------------
 * The top and side menus share one route registry. Hidden navigation is not a
 * separate app. Change ROUTES, and both menus and active states update.
 */
const ROUTES=[['home','Home'],['principles','Principles'],['engines','Ten engines'],['builder','Project builder'],['workspace','Workspace'],['simulator','Model lab'],['research','Research studio'],['evidence','Evidence'],['protocol','Protocol'],['innovation','Innovation OS'],['data','Data & privacy'],['attributions','Sources & limits']];
function setupNav(){const header=document.querySelector('header.topbar'),nav=header.querySelector('.nav');nav.replaceChildren(...ROUTES.filter(r=>['home','engines','builder','workspace','simulator','research','evidence','innovation','data'].includes(r[0])).map(([id,label])=>{const a=document.createElement('a');a.href='#'+id;a.textContent=label;return a}));const button=document.createElement('button');button.type='button';button.id='menuToggle';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','sideNav');button.textContent='☰ Menu';header.querySelector('.top-actions').prepend(button);const side=document.createElement('aside');side.id='sideNav';side.className='side-nav';side.setAttribute('aria-label','Full module navigation');side.hidden=true;const sideNav=document.createElement('nav');for(const [id,label] of ROUTES){const a=document.createElement('a');a.href='#'+id;a.textContent=label;sideNav.append(a)}side.append(sideNav);document.body.insertBefore(side,document.querySelector('main'));const close=()=>{side.hidden=true;button.setAttribute('aria-expanded','false')};button.addEventListener('click',()=>{side.hidden=!side.hidden;button.setAttribute('aria-expanded',String(!side.hidden));if(!side.hidden)side.querySelector('a')?.focus()});side.addEventListener('click',e=>{if(e.target.closest('a'))close()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!side.hidden){close();button.focus()}});document.addEventListener('click',e=>{if(!side.hidden&&!side.contains(e.target)&&!button.contains(e.target))close()});window.addEventListener('hashchange',updateRoute);updateRoute();}
function updateRoute(){const target=(location.hash||'#home').slice(1),valid=ROUTES.some(r=>r[0]===target)?target:'home';document.querySelectorAll('.nav a,.side-nav a').forEach(a=>{if(a.hash==='#'+valid)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
function setupTheme(){let theme='dark';try{theme=localStorage.getItem('fn_ep_theme')||'dark'}catch{}document.documentElement.dataset.theme=theme;$('themeBtn').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('fn_ep_theme',next)}catch{};toast(next+' theme enabled')});$('printBtn').addEventListener('click',()=>window.print())}
function setupSelects(){for(const id of ['atlasFilter','projectEngine','researchEngine','evidenceModule','sourceDomain']){const sel=$(id);for(const e of ENGINES){const o=document.createElement('option');o.value=e.id;o.textContent=e.icon+' '+e.name;sel.append(o)}}const changeMetric=()=>{const engine=EBY[$('projectEngine').value];$('projectMetric').replaceChildren(...engine.metric.map(m=>{const o=document.createElement('option');o.value=m[0];o.textContent=m[1]+' ('+m[2]+')';return o}))};$('projectEngine').addEventListener('change',changeMetric);changeMetric()}
function renderModules(){const q=$('atlasSearch').value.trim().toLowerCase(),filter=$('atlasFilter').value;const filtered=ENGINES.filter(e=>(filter==='all'||e.id===filter)&&[e.name,e.subtitle,e.research,e.mechanism,e.problem,e.science,e.pilot,e.metric.map(m=>m[1]).join(' ')].join(' ').toLowerCase().includes(q));$('moduleGrid').innerHTML=filtered.map((e,i)=>`<details class="panel module" id="engine-${e.id}"><summary><span class="module-number">ENGINE ${String(ENGINES.indexOf(e)+1).padStart(2,'0')} / 10 · ${e.icon}</span><h3>${clean(e.name)}</h3><p>${clean(e.subtitle)}</p></summary><div class="module-body"><p><strong>Observed problem:</strong> ${clean(e.problem)}</p><p><strong>Mechanism:</strong> ${clean(e.mechanism)}</p><h4>Research synthesis · snapshot ${SNAPSHOT}</h4><p>${clean(e.research)}</p><h4>Doctoral lens, simplified</h4><p>${clean(e.science)}</p><div class="note"><strong>Small pilot:</strong> ${clean(e.pilot)}</div><div class="note caution"><strong>Rival explanation / failure:</strong> ${clean(e.counter)}</div><div class="note danger-note"><strong>Safety and rights:</strong> ${clean(e.critical)}</div><h4>Outcome indicators</h4><ul class="mini-list">${e.metric.map(m=>`<li>${clean(m[1])} · ${clean(m[2])} · desired direction: ${m[3]==='up'?'increase':'decrease'}</li>`).join('')}</ul><h4>Source trail</h4><ul class="mini-list">${e.sources.map(id=>{const s=sourceById[id];return s?`<li><a href="${clean(s.url)}" rel="noopener noreferrer" target="_blank">[${clean(id)}] ${clean(s.org)}, ${clean(s.year)}</a></li>`:''}).join('')}</ul><p class="small">Conceptual connections: ${e.links.map(id=>clean(EBY[id].name)).join(' · ')}.</p><button type="button" data-engine="${e.id}" class="primary">Use this engine →</button></div></details>`).join('')||'<p class="panel">No matching engine. Try a broader search.</p>';$('moduleCount').textContent=filtered.length+' / 10 engines shown.';}
function chooseEngine(id){$('projectEngine').value=id;$('projectEngine').dispatchEvent(new Event('change'));$('projectTitle').value=EBY[id].name+' — local pilot';$('projectProblem').value=EBY[id].problem;$('projectContext').value='Adapt proposed pilot to local permissions, participation and capacity. '+EBY[id].critical;jump('builder');$('projectProblem').focus()}
function renderHUD(){const tasks=state.projects.flatMap(p=>p.tasks),completed=tasks.filter(t=>t.done).length,measurements=state.projects.reduce((n,p)=>n+p.observations.length,0),xp=state.projects.length*10+completed*3+measurements*5+state.evidence.length*4;$('statProjects').textContent=state.projects.length;$('statTasks').textContent=completed;$('statMeasurements').textContent=measurements;$('statEvidence').textContent=state.evidence.length;$('xp').textContent=xp;$('level').textContent=1+Math.floor(Math.sqrt(xp/50));$('hudProgress').style.width=tasks.length?Math.round(100*completed/tasks.length)+'%':'0%';const earned=[state.projects.length&&'🌱 Pilot initiated',measurements&&'📏 Observation logged',state.evidence.length&&'🔎 Evidence noted',state.projects.length>=3&&'🧩 Three projects',completed>=10&&'🛠️ Ten documented tasks'].filter(Boolean);$('badgeList').innerHTML=(earned.length?earned:['No badges earned yet']).map(x=>`<span class="tag">${clean(x)}</span>`).join('')}
function renderAll(){renderHUD();renderModules();renderProjects();renderEvidence();renderSources();renderDependencies();renderGenomeLibrary();}
/* SECTION 5: PILOT OPERATIONS -----------------------------------------------
 * Progress is documentation, not an impact rating. Only user-entered
 * observations can appear as measurements. Comparison is descriptive.
 */
function renderProjects(){if(!state.projects.some(p=>p.id===activeProject))activeProject=state.projects[0]?.id||null;$('projectList').innerHTML=state.projects.map(p=>{const done=p.tasks.filter(t=>t.done).length,percent=p.tasks.length?Math.round(100*done/p.tasks.length):0;return `<article class="panel project-card"><span class="tag">${clean(EBY[p.engine].icon+' '+EBY[p.engine].name)}</span><h3>${clean(p.title||'Untitled pilot')}</h3><p class="small">${clean(p.scale)} · ${p.window}-day review · ${done}/${p.tasks.length} documented tasks</p><div class="progress" aria-label="Task completion: ${percent} percent"><span style="width:${percent}%"></span></div><p class="small">${p.observations.length} observations · ${clean(p.created?.slice(0,10)||'Date not recorded')}</p><div class="controls"><button type="button" class="${p.id===activeProject?'primary':''}" data-open-project="${clean(p.id)}">${p.id===activeProject?'Selected':'Open project'}</button><button type="button" data-remove-project="${clean(p.id)}">Delete…</button></div></article>`}).join('')||'<div class="panel"><h3>No projects yet</h3><p>Start with an engine and build a project. All measurements stay on your device until you explicitly export a file.</p><a class="button primary" href="#builder">Create a project →</a></div>';renderProjectDetail()}
function renderProjectDetail(){const p=state.projects.find(p=>p.id===activeProject);if(!p){$('projectDetail').innerHTML='<p class="muted">Create or open a project to view its checklist and measurements.</p>';return}const e=EBY[p.engine],m=e.metric.find(x=>x[0]===p.metric)||e.metric[0],observed=p.observations.filter(o=>validNum(o.value)),latest=observed.at(-1),first=observed[0],delta=first&&latest&&observed.length>=2?latest.value-first.value:null;const tasks=p.tasks.map((t,i)=>`<label class="task ${t.done?'done':''}"><input data-task="${i}" type="checkbox" ${t.done?'checked':''}><span>${clean(t.label)}</span></label>`).join('');const obs=p.observations.map(o=>`<li><strong>${clean(o.date?.slice(0,10)||'Undated')}</strong> · ${validNum(o.value)?fmt(o.value)+' '+clean(o.unit):'Qualitative note'} · ${clean(o.method||'Method not documented')}${o.note?`<p class="small">${clean(o.note)}</p>`:''}</li>`).join('')||'<li>No observations recorded.</li>';$('projectDetail').innerHTML=`<span class="tag">${clean(e.icon+' '+e.name)}</span><h3>${clean(p.title)}</h3><p>${clean(p.problem||'No problem description in this record.')}</p><p><strong>Constraints:</strong> ${clean(p.context||'Not recorded.')}</p><div class="grid three"><div class="metric"><b>Budget available</b>${fmt(p.budget)} local currency units</div><div class="metric"><b>Primary metric</b>${clean(m[1])} (${clean(m[2])})</div><div class="metric"><b>Baseline / target</b>${p.baseline===null?'Not entered':fmt(p.baseline)} / ${p.target===null?'Not entered':fmt(p.target)}</div></div><h4>Seven-stage starter checklist</h4><div class="tasks">${tasks}</div><p class="small">Checks represent documented actions only. Independently verify results and obtain all necessary approvals.</p><h4>Measurement & reflection</h4><p class="small">Use the same unit, method, sample, and time period for comparisons. Avoid any personal identifiers in notes.</p><form id="observationForm" class="field-grid"><div><label for="obsValue">Observed value (optional)</label><input id="obsValue" type="number" step="any" placeholder="Measured ${clean(m[2])}"></div><div><label for="obsUnit">Unit</label><input id="obsUnit" maxlength="80" value="${clean(m[2])}" required></div><div class="wide"><label for="obsMethod">How was this measured?</label><input id="obsMethod" maxlength="420" placeholder="Instrument, sample, source, uncertainty..." required></div><div class="wide"><label for="obsNote">Observation, limitations, or adverse effects</label><textarea id="obsNote" maxlength="1000" placeholder="Include failures, conditions and contradictory observations."></textarea></div><button type="submit" class="primary">Record observation</button></form><div class="paper"><h4>Descriptive change only</h4><p>${delta===null?'At least two numeric observations are required for a change calculation.':`${fmt(first.value)} → ${fmt(latest.value)} ${clean(latest.unit)}; difference ${delta>0?'+':''}${fmt(delta)} ${clean(latest.unit)}. ${m[3]==='up'?'Higher':'Lower'} is the chosen direction of improvement; this comparison cannot establish a causal effect.`}</p><p class="small">No quantitative impact claim is generated. Method change, seasonality, sample selection and concurrent interventions can alter observed differences.</p><h4>Observation log</h4><ol class="mini-list">${obs}</ol></div><p class="small">Created ${clean(p.created)} · local record ${clean(p.id)}</p>`;$('observationForm').addEventListener('submit',async ev=>{ev.preventDefault();const value=asNum($('obsValue').value),method=$('obsMethod').value.trim(),unit=$('obsUnit').value.trim();if(value!==null&&!validNum(value))return toast('Enter a finite observed number.');if(!method||!unit)return toast('Record a method and unit.');if(p.observations.length>=500)return toast('Observation limit reached: export this project.');p.observations.push({id:makeId(),date:now(),value,unit:text(unit,80),method:text(method,420),note:text($('obsNote').value,1000)});await persist();renderProjects();renderHUD();toast('Observation recorded locally. Not externally verified.')})}
function buildProject(ev){ev.preventDefault();if(!ev.currentTarget.reportValidity())return;const engine=EBY[$('projectEngine').value];if(state.projects.length>=200)return toast('Project limit reached. Export an archive first.');const baseline=asNum($('projectBaseline').value),target=asNum($('projectTarget').value);if([baseline,target].some(n=>n!==null&&!validNum(n)))return toast('Invalid numeric field.');const p={id:makeId(),engine:engine.id,title:text($('projectTitle').value.trim(),120),problem:text($('projectProblem').value.trim()),context:text($('projectContext').value.trim(),1300),budget:Number($('projectBudget').value)||0,scale:$('projectScale').value,metric:$('projectMetric').value,window:Number($('projectTime').value),baseline,target,created:now(),review:'',tasks:engine.tasks.map(label=>({label,done:false})),observations:[]};state.projects.push(p);activeProject=p.id;persist().then(()=>{$('builderStatus').textContent='Project added to '+storeMode+'.';renderProjects();renderHUD();toast('Created '+p.title);jump('workspace')})}
/* SECTION 6: DIMENSIONALLY EXPLICIT MODELS ----------------------------------
 * Defaults are illustrations, not literature coefficients. Min/max change the
 * key uncertain parameter only; they are not confidence intervals.
 */
const MODELS={
food:{fields:[['area','Cultivated area','m²',30,0,100000],['yield','Observed or assumed usable yield','kg/m² per season',2,0,1000],['edible','Edible fraction','fraction 0–1',.85,0,1],['serving','Mass per produce serving','kg/serving',.08,.001,10]],key:'yield',explain:'The yield input is a user assumption or locally measured value, not a universal crop benchmark.',fn:v=>({value:v.area*v.yield*v.edible/v.serving,unit:'illustrative produce servings',extra:`Edible harvest: ${fmt(v.area*v.yield*v.edible)} kg. This is a mass-equivalence, NOT nutritional adequacy, dietary diversity, guaranteed harvest or proof of better access.`,formula:'area (m²) × yield (kg/m²) × edible fraction ÷ serving mass (kg/serving)'})},
energy:{fields:[['capacity','Battery nameplate capacity','Wh',1500,.001,1e9],['usable','Fraction available after reserves','fraction 0–1',.8,0,1],['load','Average continuous load','W',150,.001,1e8],['efficiency','System discharge efficiency','fraction 0–1',.88,0,1]],key:'load',explain:'This is an idealized electrical energy balance, not equipment sizing.',fn:v=>({value:v.capacity*v.usable*v.efficiency/v.load,unit:'illustrative hours',extra:'Does not assess load surge, inverter ratings, charge state accuracy, ambient temperature, battery damage, fire risk, or medical-device reliability. Use a qualified professional for critical loads.',formula:'capacity (Wh) × usable fraction × efficiency ÷ load (W)'})},
repair:{fields:[['replacement','Replacement purchase cost','local currency',240,0,1e9],['disposal','Disposal and acquisition costs','local currency',15,0,1e9],['repair','Repair and parts cost','local currency',110,0,1e9],['transport','Travel, downtime and other repair costs','local currency',20,0,1e9]],key:'repair',explain:'Comparable service life, function, warranties and safety must be checked separately.',fn:v=>({value:(v.replacement+v.disposal)-(v.repair+v.transport),unit:'local currency difference (positive favors repair)',extra:'Illustrative purchase-cost comparison only. It excludes future failures, operating efficiency, discount rates and life-cycle environmental impacts.',formula:'(replacement + disposal) − (repair + repair travel/downtime)'})},
ecology:{fields:[['planted','Originally tagged individuals','count',100,1,1e7],['alive','Still alive on fixed census date','count',72,0,1e7],['missing','Missing or unverified tags','count',6,0,1e7]],key:'alive',explain:'Unknown tagged individuals cannot silently be excluded from the denominator.',fn:v=>{if(v.alive+v.missing>v.planted)throw Error('Alive + missing exceeds original tagged plants. Recheck census.');return {value:100*v.alive/v.planted,unit:'% confirmed survival (conservative)',extra:`${fmt(v.missing,0)} individuals remain unverified. If all missing prove alive, upper descriptive bound is ${fmt(100*(v.alive+v.missing)/v.planted)}%. Survival alone does not measure ecosystem recovery.`,formula:'100 × confirmed live / originally tagged'}}}
};
function renderModelFields(){const m=MODELS[$('modelType').value];$('modelFields').innerHTML=m.fields.map(([id,label,unit,value,min,max])=>`<div><label for="model_${id}">${clean(label)} <span class="small">(${clean(unit)})</span></label><input id="model_${id}" type="number" min="${min}" max="${max}" step="any" value="${value}" required></div>`).join('');$('modelResult').textContent='These defaults illustrate calculations. Replace every input with locally verified quantities.'}
function computeModel(model,v,sensitivity){const m=MODELS[model];for(const [id,label,unit,_,min,max] of m.fields){if(!validNum(v[id])||v[id]<min||v[id]>max)throw Error(label+' must be between '+min+' and '+max)}const middle=m.fn(v);const key=m.key,lower={...v,[key]:v[key]*(1-sensitivity)},upper={...v,[key]:v[key]*(1+sensitivity)};const results=[m.fn(lower).value,m.fn(upper).value];return {...middle,min:Math.min(...results),max:Math.max(...results)}}
function runModel(){const name=$('modelType').value,m=MODELS[name],v=Object.fromEntries(m.fields.map(f=>[f[0],Number($('model_'+f[0]).value)]));try{for(const f of m.fields)if(!$('model_'+f[0]).value.trim())throw Error('Fill in '+f[1]);const r=computeModel(name,v,Number($('sensitivity').value)/100),range=Math.max(1,Math.abs(r.min),Math.abs(r.max));$('modelResult').innerHTML=`<h3>${fmt(r.value)} ${clean(r.unit)}</h3><p><strong>Arithmetic:</strong> ${clean(r.formula)}</p><div class="metric"><b>One-factor sensitivity illustration (not probability or confidence)</b>${fmt(r.min)} to ${fmt(r.max)} ${clean(r.unit)}<div class="bar" aria-hidden="true"><span style="width:${Math.round(100*Math.max(0,Math.abs(r.value))/range)}%"></span></div></div><p>${clean(r.extra)}</p><p class="small">${clean(m.explain)} Varying only “${clean(m.fields.find(f=>f[0]===m.key)[1])}” by ±${$('sensitivity').value}%; all other values held fixed. Inputs supplied by user/default illustration; no live source or calibrated uncertainty model.</p>`}catch(e){$('modelResult').textContent='Cannot calculate: '+e.message}}
/* SECTION 7: RECURSIVE RESEARCH ENGINE --------------------------------------
 * Deterministic synthesis; no remote model, pretending to browse, or invented
 * studies. Every answer has a supported part and an unresolved part.
 * Expansion prompt: "Conduct a PRISMA-scoped search for the current domain;
 * screen primary studies; distinguish review/guideline/experiment; report
 * effect size, confidence interval, populations, nulls and DOI provenance."
 */
const RESEARCH_AXES=[
['Need and population','Who defines the problem, whose needs or rights are missing, and what is the baseline?','The registry specifies a candidate problem, not a verified local baseline. Interview affected people with consent; disaggregate access only where privacy permits.'],
['Evidence strength','Which exact population, study design, comparator and measured outcomes support the proposal?','Curated references describe relevant research or practice guidance. No source in this file alone validates this specific local intervention. Read methods and estimate applicability.'],
['Mechanism and alternatives','By what mechanism could this work, and which less complex alternatives deserve comparison?','The domain registry supplies a plausible mechanism and a competing explanation. Compare service delivery, affordability and maintenance—not just technology.'],
['Safety and governance','Who bears risk, who can refuse, and what permits or expert review are needed?','Use the domain safeguard and local rules before starting. Stop where qualified supervision or permission is required.'],
['Outcome measurement','What would count as a meaningful outcome, measured when and how?','Choose one primary metric, lock its unit and denominator before work, record missingness and adverse events. Tasks completed are not outcomes.'],
['Causal inference','What other change could explain the observation and what comparison is feasible?','A before–after difference is descriptive only. Consider seasonality, self-selection, displacement, secular trends and comparator integrity.'],
['Falsification','What evidence would make us abandon or alter the proposal?','Specify a stop rule for harm, unacceptable burden or a measured failure to achieve minimum meaningful improvement. Record negative findings.'],
['Equity and scalability','Who might be excluded if scaled and who pays long-run upkeep?','Audit participation barriers, land and data rights, costs, staff capacity and maintenance. Replicate independently before claiming transferability.']
];
function researchBundle(engineId,challenge,audience,boundary,mode){const e=EBY[engineId]||ENGINES[0],refs=e.sources.map(id=>sourceById[id]).filter(Boolean),claim=challenge.trim()||e.problem,questions=RESEARCH_AXES.map(([name,question,answer],i)=>({name,question,answer:i===2?`Hypothesized mechanism: ${e.mechanism} Competing account: ${e.counter} ${answer}`:i===3?`${e.critical} Explicit boundary: ${boundary||'Ask participants to define the boundary.'} ${answer}`:i===4?`Candidate metric: ${e.metric[0][1]} (${e.metric[0][2]}). ${answer}`:answer,unresolved:i===0?'Actual beneficiary priorities, denominator and baseline are unknown.':i===1?'Study quality and locally applicable effect sizes need independent examination.':i===3?'Applicable permits and expert assessment have not been checked.':i===4?'Baseline distribution, precision and minimally meaningful effect are unmeasured.':'Requires a local, consented investigation.'}));const steps=['Discover: search up-to-date primary studies and policy guidance, log search dates and exact inclusion criteria.','Challenge: construct the strongest credible null hypothesis, non-technical alternative and failure path.','Co-design: consult affected people, rights holders, experienced practitioners and those likely to be excluded.','Prototype: specify one low-risk pilot, controls, stopping conditions, sample and accessible fallback.','Verify: freeze the indicator and method, log observations and adverse effects, invite independent review.','Transfer: release only licensed, permissioned, de-identified material; test in another context before scaling.'];const promptChain=[
`DISCOVER | Date-check the literature. Domain: ${e.name}. Problem: ${claim}. Decision-makers: ${audience}. Find 2024–2026+ systematic reviews, registered trials, datasets, relevant standards and primary studies. Search beyond English where feasible. Produce a deduplicated evidence table containing title, DOI, publication date, sample/population, comparator, outcome, effect/uncertainty, limitations, license, geographic transferability and any retractions. Do not fabricate citations. Start with source IDs: ${e.sources.join(', ')}; verify each original. Identify major missing evidence.`,
`ADVERSARIAL VALIDATION | Challenge the proposal "${claim}" without presuming success. Identify at least four plausible alternative explanations, confounders, publication/selection bias, negative effects and opportunity costs. Compare the non-technological alternative. Write explicit falsification and stopping criteria. Safety boundary: ${boundary}.`,
`CO-DESIGN & PILOT | Design a voluntary ${e.name} pilot for ${audience}. Translate expert science into plain-language steps; specify local permissions, risk owners, safeguarding, accessibility, culturally appropriate co-governance, maintenance, costs and alternatives. Starting pilot: ${e.pilot} Define a realistic control or comparison where ethical.`,
`PREREGISTER & VERIFY | Primary outcome metric: ${e.metric[0][1]} in ${e.metric[0][2]}. Choose a meaningful target with justification, sampling frame, baseline, instrument calibration, follow-up, missingness protocol and honest uncertainty. Avoid claiming causation from a before–after observation. Report nulls, adverse effects, subgroup burdens and data-quality flags.`,
`INDEPENDENT REVIEW | Have qualified domain practitioners and affected participants audit factual accuracy, measurement reproducibility, permissions, consent, disparate harms, source links and conflicts of interest. State unresolved risks and whether evidence justifies continuing, revising or stopping. Do not issue certification from model output.`,
`REPLICATION & TRANSFER | Package methods, schema, provenance, dependency versions, instructions, safety boundaries, negative findings and an accessible offline copy. Respect open-source licenses, Indigenous data sovereignty, personal privacy and permission revocation BEFORE transfer. Compare replication outcome across new sites and document non-transferable conditions.`
];const lines=[`FOSTER + NAVI · EVIDENCE-BOUNDED RESEARCH BRIEF · ${new Date().toISOString().slice(0,10)}`,`Snapshot: ${SNAPSHOT} · Domain: ${e.name} · Mode: ${mode.toUpperCase()}`,`Research challenge: ${claim}`,`Intended participants: ${audience}`,`Safety/consent boundary: ${boundary}`,`KNOWN FROM CURATED SNAPSHOT (NOT A LOCAL TRIAL): ${e.research}`,`WORKING MECHANISM: ${e.mechanism}`,`COUNTERARGUMENT: ${e.counter}`,`SAFE START: ${e.pilot}`,`NONNEGOTIABLE: ${e.critical}`,...questions.map((x,i)=>`${i+1}. ${x.name}\nQUESTION: ${x.question}\nWORKING ANSWER: ${x.answer}\nUNRESOLVED: ${x.unresolved}`),`CANDIDATE MEASURES: ${e.metric.map(m=>m[1]+' ['+m[2]+', desired '+m[3]+']').join('; ')}`,`REVIEWED REFERENCE POINTERS (verify current originals):`,...refs.map(s=>`${s.id} ${s.org} ${s.year}: ${s.title}\n${s.url}\nLIMITATION: ${s.limit}`),`PROCEDURE:`,...steps.map((s,i)=>`${i+1}. ${s}`),'PROVENANCE STATUS: Generated deterministically from locally embedded summaries and user input. No live search, AI inference service, statistical analysis, expert certification or field validation.'];return {e,claim,questions,steps,promptChain,refs,text:lines.join('\n\n')}}
function runResearch(ev){if(ev)ev.preventDefault();const bundle=researchBundle($('researchEngine').value,$('researchChallenge').value,$('researchAudience').value,$('researchBoundary').value,$('researchDepth').value);researchText=bundle.text;promptText=bundle.promptChain.join('\n\n'+'─'.repeat(30)+'\n\n');const show=$('researchDepth').value==='field'?bundle.questions.filter((q,i)=>[0,2,3,4,6].includes(i)):bundle.questions;const cards=show.map((q,i)=>`<article class="panel"><span class="tag">${String(i+1).padStart(2,'0')} · ${clean(q.name)}</span><h3>${clean(q.question)}</h3><p><strong>Working answer:</strong> ${clean(q.answer)}</p><p class="warning"><strong>Still unknown:</strong> ${clean(q.unresolved)}</p></article>`).join('');$('researchOutput').innerHTML=`<article class="panel wide"><span class="tag">LOCAL DETERMINISTIC SYNTHESIS · NOT A LIVE AI</span><h3>${clean(bundle.e.icon+' '+bundle.e.name)}</h3><p><strong>Question:</strong> ${clean(bundle.claim)}</p><p>${clean(bundle.e.research)}</p><p class="small">Evidence ≠ local proof. Open the source trail and check dates, populations and methods. Every generated answer below has an unresolved dependency.</p></article>${cards}`;$('promptChain').innerHTML=bundle.promptChain.map((prompt,i)=>`<article class="panel"><span class="tag">PROMPT ${i+1} / ${bundle.promptChain.length}</span><h3>${clean(['Literature discovery','Counterargument','Ethical pilot design','Preregistered evaluation','Independent audit','Replication package'][i])}</h3><details><summary>Inspect complete prompt</summary><pre class="prompt">${clean(prompt)}</pre></details><button type="button" data-copy-prompt="${i}">Copy this prompt</button></article>`).join('');toast('Generated '+bundle.questions.length+' evidence-bound research questions and '+bundle.promptChain.length+' prompts.');}
