function renderSources(){const q=$('sourceSearch').value.trim().toLowerCase(),domain=$('sourceDomain').value;const result=SOURCES.filter(s=>(domain==='all'||s.domain===domain)&&[s.id,s.org,s.title,s.take,s.limit,s.year].join(' ').toLowerCase().includes(q));$('sourceList').innerHTML=result.map(s=>`<article class="panel source"><span class="tag">${clean(s.id)} · ${clean(s.year)}</span><h3>${clean(s.title)}</h3><p class="small">${clean(s.org)}</p><p><strong>Application:</strong> ${clean(s.take)}</p><p class="warning"><strong>Limit:</strong> ${clean(s.limit)}</p><a target="_blank" rel="noopener noreferrer" href="${clean(s.url)}">Open original source ↗</a></article>`).join('')||'<p class="panel">No matching source in the fixed snapshot.</p>'}
function renderEvidence(){$('evidenceNotes').innerHTML=state.evidence.map(n=>`<article class="panel"><span class="tag">${clean(EBY[n.domain].name)} · ${clean(n.type)}</span><h3>${clean(n.claim||'Claim redacted in shared backup')}</h3><p class="small">User-selected evidence category: ${clean(n.quality)} · ${clean(n.date?.slice(0,10))}</p>${n.url?`<p><a href="${clean(n.url)}" rel="noopener noreferrer" target="_blank">User-provided source ↗</a> (not verified by application)</p>`:''}<p><strong>Limits / opposition:</strong> ${clean(n.limits||'Not entered')}</p><button type="button" data-delete-evidence="${clean(n.id)}">Delete note…</button></article>`).join('')||'<p class="panel">Your local evidence ledger is empty. Published reference cards above are not your own verified findings.</p>'}
function addEvidence(ev){ev.preventDefault();if(!ev.currentTarget.reportValidity())return;if(state.evidence.length>=500)return toast('Evidence limit reached; export a backup.');try{state.evidence.push({id:makeId(),domain:$('evidenceModule').value,type:$('evidenceType').value,claim:text($('evidenceClaim').value.trim(),1200),url:validateURL($('evidenceUrl').value.trim()),quality:$('evidenceQuality').value,limits:text($('evidenceLimits').value.trim(),1200),date:now()});persist().then(()=>{renderEvidence();renderHUD();$('evidenceForm').reset();toast('Unverified user evidence note saved locally.')})}catch(e){toast(e.message)}}
/* SECTION 9: CROSS-DOMAIN METHODS ------------------------------------------
 * SVG is conceptual, not a statistically inferred causal network.
 */
const METHOD_CARDS=[['Logic model','Inputs → activities → outputs → outcomes → impact; inspect every arrow, not just the endpoint.','Example: seedlings and planting days are outputs; multi-year native ecological recovery is an outcome.'],['Counterfactual','The difference between an observed outcome and what would have happened without the intervention.','Where feasible, use consented comparison groups, matched baselines and sensitivity checks.'],['Sampling & missingness','Specify eligible population, selection, unit of analysis, measurement dates and reasons data are missing.','Avoid treating only enthusiastic respondents as representative.'],['Uncertainty & sensitivity','Separate instrument error, natural variability, model assumptions and inferential uncertainty.','A ±20% scenario slider is not a confidence or credible interval.'],['Life-cycle perspective','Track acquisition, operating energy, material flows, disposal, durability and rebound effects.','Local production and repair are not inherently lower-emission without a common functional unit.'],['Equity & rights','Ask who defines success, who bears costs, who can refuse, who owns data, and who receives benefits.','Co-governance and accessibility are implementation requirements, not decorative features.']];
const GLOSSARY=[['Baseline','A measured starting value collected before action using a documented method.'],['Comparator','The condition or group against which an intervention is evaluated.'],['Confounder','A factor related to both intervention selection and the outcome that can distort an association.'],['Counterfactual','What would have happened without the intervention; rarely directly observable.'],['External validity','Whether findings generalize to a different population, place or season.'],['FAIR / CARE','FAIR guides findability, accessibility, interoperability and reuse; CARE concerns collective benefit, authority to control, responsibility and ethics in Indigenous data governance.'],['Functional unit','A shared service basis for life-cycle comparison, e.g. one functioning appliance-year.'],['Measurement error','Difference between observed measurement and the value the measure is intended to represent.'],['Preregistration','Recording hypotheses, primary outcomes and analysis decisions before observing results.'],['Rebound effect','Efficiency savings induce additional activity that offsets some expected resource reductions.'],['Risk owner','Named person or organization accountable for identifying, monitoring and responding to a specific harm.'],['Selection bias','Systematic distortion when who participates or remains in a sample differs from the target population.'],['Stopping rule','A condition set before a pilot that requires pause, revision or termination.'],['Triangulation','Examine claims using independent methods or sources with different vulnerabilities.']];
function svg(tag,attrs,textValue){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [name,value] of Object.entries(attrs))e.setAttribute(name,String(value));if(textValue!==undefined)e.textContent=textValue;return e}
function renderDependencies(){const root=$('dependencyGraph');root.replaceChildren(svg('title',{},'Conceptual network, ten independent domains linked to one shared protocol'));const cx=475,cy=205;const positions=ENGINES.map((e,i)=>({e,x:cx+355*Math.cos(2*Math.PI*i/10-Math.PI/2),y:cy+155*Math.sin(2*Math.PI*i/10-Math.PI/2)}));positions.forEach(p=>root.append(svg('line',{x1:cx,y1:cy,x2:p.x,y2:p.y})));positions.forEach(p=>{root.append(svg('circle',{cx:p.x,cy:p.y,r:27}));root.append(svg('text',{x:p.x,y:p.y+4,'text-anchor':'middle'},p.e.icon));root.append(svg('text',{x:p.x,y:p.y+43,'text-anchor':'middle'},p.e.name.split(' ')[0]))});root.append(svg('circle',{cx,cy,r:46}));root.append(svg('text',{x:cx,y:cy-3,'text-anchor':'middle'},'SHARED'));root.append(svg('text',{x:cx,y:cy+15,'text-anchor':'middle'},'PROTOCOL'));$('dependencyLinks').innerHTML=ENGINES.map(e=>`<div class="metric"><b>${clean(e.icon+' '+e.name)}</b>${e.links.map(id=>clean(EBY[id].name)).join(' · ')}</div>`).join('');$('methods').innerHTML=METHOD_CARDS.map(m=>`<article class="method"><h3>${clean(m[0])}</h3><p>${clean(m[1])}</p><p class="small">${clean(m[2])}</p></article>`).join('');$('glossary').innerHTML=GLOSSARY.map(([term,def])=>`<dt><strong>${clean(term)}</strong></dt><dd>${clean(def)}</dd>`).join('');$('lifecycle').innerHTML=['Diagnose · user-defined need','Review · evidence and counterclaims','Govern · rights, permits and safeguards','Prototype · low-risk field plan','Measure · methods, baseline and adverse effects','Replicate · qualified review and informed reuse'].map((txt,i)=>`<div class="step"><span class="orb">${i+1}</span><p>${clean(txt)}</p></div>`).join('')}
